import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const out='review-evidence/no-brow-editable-bundle',origin='http://127.0.0.1:8140';
const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});const p=await browser.newPage({viewport:{width:1600,height:715}}),errors=[];p.on('pageerror',e=>errors.push(e.message));
await p.goto(origin+'/review-evidence/selected-gesture-review/');await p.waitForFunction(()=>window.selectedReview?.ready);const live=await p.locator('#after svg').evaluate(n=>n.outerHTML);
await p.setContent('<!doctype html><style>html,body{margin:0;background:#24493b}svg{display:block;width:1600px;height:715px}svg text{font:32px system-ui,sans-serif;fill:#f1f7ee;text-anchor:middle}</style>'+live);await p.evaluate(()=>Promise.all([...document.querySelectorAll('image')].map(n=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=n.getAttribute('href')}))));const baseline=await p.screenshot();
await p.goto(origin+'/'+out+'/preview.html');await p.evaluate(()=>Promise.all([...document.querySelectorAll('image')].map(n=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=n.getAttribute('href')}))));const preview=await p.screenshot({path:out+'/Ranca-Cana-no-brows.png'});assert.ok(baseline.equals(preview),'standalone SVG/HTML export must render pixel-identically to the no-brow scene');
const count=await p.evaluate(()=>Object.fromEntries([...document.querySelectorAll('[data-character]')].map(c=>[c.dataset.character,{rasterImages:c.querySelectorAll('image').length,editablePaths:c.querySelectorAll('path').length,separateBrows:[...c.querySelector('[data-preserved-face]').children].filter(n=>n.tagName.toLowerCase()==='path'&&n!==c.querySelector('[data-preserved-face]').lastElementChild).length}])));
for(const key of ['ranca','cana']){assert.equal(count[key].rasterImages,1);assert.equal(count[key].separateBrows,0);assert.ok((await fs.readFile(out+'/assets/'+key+'-body.webp')).equals(await fs.readFile('assets/mascots/poses/'+key+'-body.webp')));}
assert.deepEqual(errors,[]);await browser.close();await fs.writeFile(out+'/export-check.json',JSON.stringify({standalonePixelIdentical:true,sourceScene:'77bafae3 with only separate eyebrows removed',layers:count,bodyImageBytesUnchanged:true,jsxValidation:'Generated as literal named SVG paths; not locally compiled. MagicPath worker must validate the imported component.',pageErrors:errors},null,2));console.log(JSON.stringify(count));
